def is_balanced(s):
    rest = "".join(ch for ch in s if ch in "()[]{}")
    while True:
        reduced = rest.replace("()", "").replace("[]", "").replace("{}", "")
        if reduced == rest:
            return rest == ""
        rest = reduced

def is_balanced(s):
    closers = {"(": ")", "[": "]", "{": "}"}
    expected = []
    for ch in s:
        if ch in closers:
            expected.append(closers[ch])
        elif ch in closers.values():
            if not expected or expected.pop() != ch:
                return False
    return len(expected) == 0
